-- Подсадка — в открытую версию: пункт судит только её (решение владельца 2026-10-07).
WITH v AS (INSERT INTO project_plan_versions (project_id, id) VALUES ($1, 'v-probe-9990') RETURNING id), новая AS (INSERT INTO project_plan_milestones (project_id, id, version_id, ord, title) SELECT $1, 'M9990', v.id, 9990, 'проба самотеста' FROM v RETURNING id), m AS (SELECT coalesce((SELECT m.id FROM project_plan_milestones m JOIN version_scope s ON s.project_id = m.project_id AND s.version = m.version_id WHERE m.project_id = $1 ORDER BY CASE coalesce(s.scope, 'open') WHEN 'open' THEN 0 WHEN 'closed' THEN 1 ELSE 2 END, m.id LIMIT 1), (SELECT id FROM новая)) AS id), t AS (INSERT INTO project_plan_tasks (project_id, id, milestone_id, ord, title, size, state, kind) SELECT $1, 'M9990-T1', m.id, 1, 'проба самотеста', 'S', 'not_started', 'dev' FROM m RETURNING id), q AS (INSERT INTO project_requirements (project_id, id, kind, area, text, satisfied, title) VALUES ($1, 'FR-PROBE-9990', 'FR', 'проба', 'проба самотеста', false, 'проба самотеста') RETURNING id), o AS (INSERT INTO project_requirement_op (project_id, requirement_id, operation) SELECT $1, q.id, 'POST /probe-selftest/9990' FROM q RETURNING requirement_id) INSERT INTO task_requirement (project_id, task_id, requirement_id) SELECT $1, t.id, q.id FROM t, q
